#include <stdio.h>

int is_perfect(int n) {
    int sum = 0;
    for (int d = 1; d < n; d++) {
        if (n % d == 0) {
            sum += d;
        }
    }
    return sum == n;
}

int main() {
    for (int n = 2; n <= 500; n++) {
        if (is_perfect(n)) {
            printf("%d is perfect\n", n);
        }
    }
    return 0;
}
